      widgets: {
        mmpnl: function (root) {
          const C = Course, f = (x, d) => C.fmt.n(+x, d);
          const S = {};
          let seed = 11;
          const N = 200;
          const out = C.ui.output(root);
          const cv = C.ui.canvas(root, 640, 300);
          // один путь: возвращает массивы накопленного дохода от спреда, переоценки и итога
          const path = (rng, h, p, sig, mu, a) => {
            const sgn = mu > 0 ? 1 : mu < 0 ? -1 : 0;
            const pa = Math.min(1, Math.max(0, p * (1 + a * sgn)));
            const pb = Math.min(1, Math.max(0, p * (1 - a * sgn)));
            let q = 0, spr = 0, rev = 0, maxq = 0;
            const sp = [0], rv = [0], tt = [0];
            for (let t = 1; t <= N; t++) {
              const u = rng();
              if (u < pa) { q -= 1; spr += h; } else if (u < pa + pb) { q += 1; spr += h; }
              const dS = mu + sig * C.rand.normal(rng);
              rev += q * dS;
              maxq = Math.max(maxq, Math.abs(q));
              sp.push(spr); rv.push(rev); tt.push(spr + rev);
            }
            return { sp: sp, rv: rv, tot: tt, q: q, maxq: maxq };
          };
          const upd = () => {
            const h = S.h.get(), p = S.p.get(), sig = S.s.get(), mu = S.m.get(), a = S.a.get();
            const one = path(C.rand.seeded(seed), h, p, sig, mu, a);
            const xs = one.tot.map((_, i) => i);
            C.plot.line(cv, {
              series: [
                { x: xs, y: one.sp, label: 'доход от спреда', color: C.ui.color('--c1') },
                { x: xs, y: one.rv, label: 'переоценка запаса', color: C.ui.color('--c2') },
                { x: xs, y: one.tot, label: 'итого P&L', color: C.ui.color('--ink') }
              ],
              xlabel: 'Шаг', ylabel: 'P&L (в единицах цены)', title: 'Один путь: из чего складывается результат'
            });
            const M = 300, r2 = C.rand.seeded(seed * 7919 + 1), res = [], qs = [];
            for (let i = 0; i < M; i++) { const o = path(r2, h, p, sig, mu, a); res.push(o.tot[N]); qs.push(Math.abs(o.q)); }
            const mean = res.reduce((x, y) => x + y, 0) / M;
            const sd = Math.sqrt(res.reduce((x, y) => x + (y - mean) * (y - mean), 0) / M);
            const neg = res.filter(v => v < 0).length / M;
            const mq = qs.reduce((x, y) => x + y, 0) / M;
            out.innerHTML = 'Этот путь: спред <b>' + f(one.sp[N], 1) + '</b>, переоценка <b>' + f(one.rv[N], 1) + '</b>, итог <b>' + f(one.tot[N], 1) + '</b>; запас в конце ' + one.q + ', макс. |запас| ' + one.maxq + '.<br>' +
              'По ' + M + ' путям: средний P&amp;L <b>' + f(mean, 1) + '</b>, стд. <b>' + f(sd, 1) + '</b>, доля убыточных путей <b>' + f(neg * 100, 0) + '%</b>, средний |запас| в конце ' + f(mq, 1) + '.';
          };
          S.h = C.ui.slider(root, { label: 'Полуспред h', min: 0, max: 2, step: 0.05, value: 0.5, fmt: v => f(v, 2), onInput: upd });
          S.p = C.ui.slider(root, { label: 'Вероятность исполнения за шаг (с каждой стороны) p', min: 0.02, max: 0.5, step: 0.01, value: 0.3, fmt: v => f(v, 2), onInput: upd });
          S.s = C.ui.slider(root, { label: 'Волатильность за шаг σ', min: 0.1, max: 2, step: 0.05, value: 1, fmt: v => f(v, 2), onInput: upd });
          S.m = C.ui.slider(root, { label: 'Дрейф mid за шаг μ', min: -0.2, max: 0.2, step: 0.01, value: 0, fmt: v => f(v, 2), onInput: upd });
          S.a = C.ui.slider(root, { label: 'Давление потока по тренду (неблагоприятный отбор)', min: 0, max: 1, step: 0.05, value: 0, fmt: v => f(v, 2), onInput: upd });
          C.ui.button(root, 'Новый случайный путь', () => { seed += 1; upd(); }, true);
          upd();
        }
      },
